svg.script:
const REPO = "https:/" + "/cdn.jsdelivr.net/gh/care24important7-cpu/my-linux@main/";
const frame = document.getElementById("linux_frame");
fetch(REPO + "desktop.html?t=" + Date.now())
  .then(r => r.text())
  .then(html => {
    const doc = frame.contentDocument || frame.contentWindow.document;
    doc.open();
    doc.write(html.replace("<head>", '<head><base href="' + REPO + '" />'));
    doc.close();
  });
